/**
 * @distilled.cloud/browserbase -- Browserbase API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` converts from the OpenAPI document mirrored at
 * `specs/spec-mirror-browserbase/specs/openapi.v1.yaml`. Everything else in
 * this folder is hand-written.
 *
 * Browserbase is one service, so its operations are exported straight off
 * the package root.
 *
 * @example
 * ```ts
 * import * as Browserbase from "@distilled.cloud/browserbase";
 *
 * const session = yield* Browserbase.createSession({});
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  BrowserbaseProtocol,
  type BrowserbaseOpError,
  type BrowserbaseOpContext,
} from "./protocol.ts";
export { paginateCursor, paginateOffset } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/browserbase.ts";
// The service-local typed error classes shadow the same-named shared ones
// from ./errors.ts -- the operations raise the service-local classes.
export {
  BadRequest,
  Conflict,
  Forbidden,
  NotFound,
  UnprocessableEntity,
} from "./services/browserbase.ts";
